const pend=KS.S.approvals.filter(a=>a.status==="Pending").length; const pipe=KS.S.deals.filter(d=>!["Won","Lost"].includes(d.stage)).reduce((a,d)=>a+(d.value||0),0)+KS.S.crm.filter(l=>l.stage!=="Won"&&l.stage!=="Lost").length*2500;
