function showScore(id,kind){ const p=KS.S.prospects.find(x=>x.id===id); if(!p) return; const W=KS.S.weights; let rows=[]; if(kind==="dq"){ rows=[["Site web",p.website?20:0],["Téléphone pro",p.phone?20:0],["Email pro",p.public_email?20:0],["Adresse",p.address?15:0],["Secteur renseigné",p.industry?15:0],["Base",10]]; } else if(kind==="rel"){ const s=KS.S.searches.find(x=>x.id===p.searchId); const ind=s?s.params.industry:p.industry_key; rows=[["Base",30],["Secteur",p.industry_key===ind?W.industry:0],["Localisation ("+p.city+")",(s&&p.city===s.params.city.city)?W.location:0],["Signaux x"+p.signals.length,Math.min(W.signals,p.signals.length*4)],["Taille ("+(p.employee_range||"?")+")",(s&&s.params.size&&p.employee_range===s.params.size)?W.size:0],["ICP fit",p.icp!=null&&p.icp>=70?5:0]]; } else if(kind==="conf"){ rows=[["Data Quality × 0,4",Math.round(p.dq*0.4)],["Pertinence × 0,6",Math.round(p.rel*0.6)]]; } else if(kind==="intent"){ const IW={"Entreprise récente":30,"Recrutement":20,"Expansion":20,"Nouveau site":15,"Présence numérique active":10,"Activité récente":10}; rows=[["Base",5]].concat(p.signals.map(sg=>[sg,IW[sg]||5])); } else { rows=[["Pertinence × 0,45",Math.round(p.rel*0.45)],["Data Quality × 0,2",Math.round(p.dq*0.2)],["Confiance × 0,15",Math.round(p.conf*0.15)],["Intent × 0,2",Math.round(E.intentOf(p)*0.2)]]; } const tot=rows.reduce((a,r)=>a+r[1],0); document.getElementById("modal").innerHTML=`<div class="modal" id="mBack"><div class="box"><h3>${({dq:"Data Quality",rel:"Relevance",conf:"Confidence",intent:"Intent",opp:"Opportunity"})[kind]||kind} — ${p.company_name}</h3>${rows.map(r=>`<div class="row"><span>${r[0]}</span><b>+${r[1]}</b></div>`).join("")}<div class="row"><span><b>Total</b></span><b>${tot}/100</b></div><p><small>Estimation calculée à partir des données publiques collectées, pas une garantie.</small></p><button class="cta" id="mClose">Fermer</button></div></div>`; document.getElementById("mClose").onclick=()=>{document.getElementById("modal").innerHTML="";}; document.getElementById("mBack").onclick=e=>{if(e.target.id==="mBack")document.getElementById("modal").innerHTML="";}; } var TOOL_DEFS={search_prospects:{risk:"read"},get_prospect:{risk:"read"},qualify_prospect:{risk:"read"},score_prospect:{risk:"read"},add_to_crm:{risk:"write"},export_prospects:{risk:"write"},generate_outreach:{risk:"write"},create_campaign:{risk:"external"},send_message:{risk:"external"}};
function runTool(name,desc,payload){const def=TOOL_DEFS[name]||{risk:"write"};
  if(def.risk==="read"){KS.audit("ai.tool.executed",name);return {auto:true};}
  const ap={id:KS.uid("ap"),tool:name,desc:desc||"",payload:payload||{},status:"Pending",at:new Date().toLocaleString()};
  KS.S.approvals.unshift(ap);KS.save();KS.notify(`Action IA nécessitant approbation : ${name} — ${desc||""}`);KS.audit("ai.tool.requested",name+" — "+(desc||""));
  return {approval:ap};}
function leadLog(l,txt){ l.log=l.log||[]; l.log.unshift({t:txt,at:new Date().toLocaleString()}); l.lastActivity=new Date().toLocaleString(); } function showLead(id){ const l=KS.S.crm.find(x=>x.id===id); if(!l)return; const p=KS.S.prospects.find(x=>x.id===l.prospectId); const d=KS.S.deals.find(dd=>dd.prospectId===l.prospectId); document.getElementById("modal").innerHTML=`<div class="modal" id="mBack"><div class="box"><h3>${l.company_name}</h3><p><small>${p?p.industry+" • ":""}${l.city}${p?" • Pertinence "+p.rel+" / Opp "+E.oppOf(p):""}</small></p><label>Étape<select id="ldStage">${["New","Contacted","Qualified","Proposal","Negotiation","Won","Lost"].map(sg=>`<option ${l.stage===sg?"selected":""}>${sg}</option>`).join("")}</select></label><div class="grid4"><label>Responsable<input id="ldOwner" value="${l.owner||""}" placeholder="Qui suit ce lead ?"></label><label>Valeur potentielle $<input id="ldValue" type="number" value="${d?d.value:(l.value||2500)}"></label></div><div class="grid4"><label>Prochaine action<input id="ldNext" value="${l.nextAction||""}" placeholder="ex : Appel de suivi"></label><label>Date de relance<input id="ldDate" type="date" value="${l.nextDate||""}"></label></div><label>Note<textarea id="ldNote" rows="2" placeholder="Ajouter une note…"></textarea></label><div class="rowb"><button class="cta" id="ldSave">Enregistrer</button><button id="ldClose">Fermer</button></div><h4>Historique</h4>${(l.log||[]).map(x=>`<div class="row"><span>${x.t}</span><small>${x.at}</small></div>`).join("")||"<small>Aucune activité.</small>"}</div></div>`; const close=()=>{document.getElementById("modal").innerHTML="";}; document.getElementById("ldClose").onclick=close; document.getElementById("mBack").onclick=e=>{if(e.target.id==="mBack")close();}; document.getElementById("ldSave").onclick=()=>{ if(window.KlirTeam&&!window.KlirTeam.guard("crm"))return;const ns=document.getElementById("ldStage").value; if(ns!==l.stage){leadLog(l,"Étape : "+l.stage+" → "+ns);l.stage=ns;} l.owner=document.getElementById("ldOwner").value; const v=parseInt(document.getElementById("ldValue").value)||0; if(d)d.value=v; else l.value=v; const na=document.getElementById("ldNext").value, nd=document.getElementById("ldDate").value; if(na!==l.nextAction||nd!==l.nextDate){leadLog(l,"Relance : "+(na||"—")+" ("+(nd||"sans date")+")");l.nextAction=na;l.nextDate=nd;} const note=document.getElementById("ldNote").value.trim(); if(note)leadLog(l,"Note : "+note); KS.save(); KS.audit("crm.lead.updated",l.company_name); close(); render(); }; } function execApproval(ap){
  if(ap.tool==="add_to_crm"){const n=KS.S.prospects.filter(p=>!p.inCrm&&(!ap.payload.filter||p.rel>=75)).slice(0,ap.payload.count||10);n.forEach(p=>{p.inCrm=true;KS.S.crm.push({id:KS.uid("l"),company_name:p.company_name,city:p.city,stage:"New",prospectId:p.id});});KS.addActivity(`Ajout CRM via Klir AI (${n.length})`);return `${n.length} prospects ajoutés au CRM. ✅`;}
  if(ap.tool==="create_campaign"){const ids=KS.S.prospects.filter(p=>p.rel>=75&&!p.inCrm).slice(0,10).map(p=>p.id);const c={id:KS.uid("c"),name:`Campagne Klir AI — ${ids.length} prospects`,prospects:ids,drafts:[],status:"Review",created:new Date().toLocaleDateString(),message:"Objet : Une question concernant votre activité"};KS.S.campaigns.unshift(c);KS.addActivity("Campagne créée (Review)");return `Campagne créée en Review : « ${c.name} ». Validez-la dans Campagnes.`;}
  if(ap.tool==="generate_outreach"){return `Rendez-vous dans Résultats, sélectionnez des prospects puis « Messages IA » — les brouillons passeront en Review.`;}
  if(ap.tool==="send_message"){const ch=KS.S.integrations.outreach;if(!ch||!ch.on)return `⛔ Envoi bloqué : aucun canal configuré (Réglages → Intégrations).`;return `Canal actif : envoi simulé enregistré au journal (aucun vrai envoi dans ce MVP local).`;}
  if(ap.tool==="export_prospects"){exportCsv();return `Export CSV lancé. ✅`;}
  return `Action ${ap.tool} exécutée.`;}
async function askAI(){const inp=document.getElementById("aiInput");const q=inp.value.trim();if(!q)return;
  KS.S.aiLog.push({me:true,t:q});inp.value="";KS.S.aiLog.push({me:false,t:"⏳ ..."});KS.save();render();
  const low=q.toLowerCase();let resp="";
  if(/trouve|cherche|search/i.test(q)){const pr=E.parseQuery(q);resp=`Je lance une recherche : ${KlirData.INDUSTRIES[pr.industry].label} à ${pr.city.city}, ${pr.quantity} prospects. Cliquez sur « Trouver mes prospects » pour l'exécuter, ou je l'ai pré-remplie pour vous.`;KS.S.prefill=q;KS.save();}
  else if(/meilleur|top|20/i.test(q)&&!(window.OppEngine&&/klirbuild|klirpromo|klir ?ia|klirpay|klirmarket|klirline/.test(low))){const top=[...KS.S.prospects].sort((a,b)=>b.rel-a.rel).slice(0,5);resp=top.length?("Vos meilleurs prospects :<br>"+top.map(p=>`• ${p.company_name} (${p.rel}/100) — ${p.city}`).join("<br>")):"Aucun prospect pour l'instant. Lancez une recherche.";}
  else if(/pourquoi|qualifi/i.test(q)){const p=[...KS.S.prospects].sort((a,b)=>b.rel-a.rel)[0];resp=p?`${p.company_name} est qualifié car : ${p.ai} (Q:${p.dq}, R:${p.rel})`:"Lancez d'abord une recherche.";}
  else if(/aujourd|relance|suivi|recontacter/i.test(q)){ const today=new Date().toISOString().slice(0,10); const due=KS.S.crm.filter(l=>l.nextDate&&l.nextDate<=today&&l.stage!=="Won"&&l.stage!=="Lost"); resp=due.length?("À recontacter :<br>"+due.slice(0,10).map(l=>`• ${l.company_name} — ${l.nextAction||"relance"} (${l.nextDate})`).join("<br>")):"Aucune relance due. Définissez des dates de relance dans vos fiches leads."; } else if(/message|prépare|campagne/i.test(q)){runTool("generate_outreach","préparer des brouillons",{});resp="J'ai placé une demande « generate_outreach » en approbation ci-dessus. Les brouillons passeront par une campagne en Review (revue humaine obligatoire).";}
  else if(window.OppEngine&&/klirbuild|klirpromo|klir ?ia|klirpay|klirmarket|klirline/.test(low)&&/meilleur|top|20|potentiel|priorité|priorite/.test(low)){const pf=window.OppEngine.parse(low);const svc=pf.service||"KLIRBUILD";const arr=KS.S.prospects.map(p=>window.OppEngine.ensure(p)).filter(p=>p.opp_top_service===svc).sort((a,b)=>((b.opp_services||{})[svc]||0)-(((a.opp_services||{})[svc]||0)));resp=arr.length?("Vos meilleurs prospects pour "+svc+" :<br>"+arr.slice(0,5).map(p=>`• ${p.company_name} — match ${((p.opp_services||{})[svc]||0)}/100, opportunité ${p.opp_score==null?"n.d.":p.opp_score} (${p.opp_priority||"—"})`).join("<br>")):"Aucun prospect avec forte correspondance pour "+svc+" pour l'instant.";}
  else if(window.OppEngine&&/pourquoi.*(numéro 1|numero 1|premier|number 1|classé|rank)|why.*(1|first)/.test(low)){const arr=KS.S.prospects.map(p=>window.OppEngine.ensure(p)).filter(p=>p.opp_score!=null).sort((a,b)=>b.opp_score-a.opp_score);const p0=arr[0];resp=p0?(`<b>${p0.company_name}</b> est classé n°1 car : opportunité ${p0.opp_score}/100 (${p0.opp_priority}) — ICP ${p0.opp_icp}, signaux ${p0.opp_signal_score}, besoin ${p0.opp_need}, ${p0.opp_top_service_label}. Signaux clés : ${((p0.opp_signals||[]).slice(0,4).map(g=>g.signal_name).join(", "))||"—"}.`):"Lancez d'abord une recherche.";}
  else if(window.OppEngine&&/besoin marketing|marketing need|fort.*marketing/.test(low)){const arr=KS.S.prospects.map(p=>window.OppEngine.ensure(p)).filter(p=>(p.opp_needs&&p.opp_needs.marketing>=65)).sort((a,b)=>b.opp_needs.marketing-a.opp_needs.marketing);resp=arr.length?("Prospects à fort besoin marketing :<br>"+arr.slice(0,8).map(p=>`• ${p.company_name} — besoin marketing ${p.opp_needs.marketing}/100`).join("<br>")):"Aucun fort besoin marketing détecté pour l'instant.";}
  else if(window.OppEngine&&/opportunit.*(80|85|90|supérieur|superieur)|score.*(80|85|90)/.test(low)){const m=low.match(/(\d{2,3})/);const th=m?parseInt(m[1]):80;const arr=KS.S.prospects.map(p=>window.OppEngine.ensure(p)).filter(p=>p.opp_score!=null&&p.opp_score>=th).sort((a,b)=>b.opp_score-a.opp_score);resp=arr.length?(`Prospects opportunité ≥ ${th} (${arr.length}) :<br>`+arr.slice(0,10).map(p=>`• ${p.company_name} — ${p.opp_score} (${p.opp_priority}, ${p.opp_top_service_label})`).join("<br>")):`Aucun prospect ≥ ${th} pour l'instant.`;}
  else if(window.OppEngine&&/contacter aujourd|contact today|que faire|priorité|priorite|qui.*contact/.test(low)){const arr=KS.S.prospects.map(p=>window.OppEngine.ensure(p)).filter(p=>!p.inCrm&&p.opp_score!=null).sort((a,b)=>b.opp_score-a.opp_score).slice(0,5);resp=arr.length?("À contacter en priorité :<br>"+arr.map((p,i)=>`${i+1}. <b>${p.company_name}</b> — opportunité ${p.opp_score}, ${p.opp_top_service_label}. Action : ${p.opp_action}`).join("<br>")):"Aucune opportunité à contacter (lancez une recherche).";}
  else if(window.OppEngine&&/quelle offre|quel service|which (service|offer)/.test(low)){const arr=KS.S.prospects.map(p=>window.OppEngine.ensure(p)).filter(p=>p.opp_score!=null).sort((a,b)=>b.opp_score-a.opp_score);const p0=arr[0];resp=p0?(`Pour <b>${p0.company_name}</b>, l'offre la plus pertinente est <b>${p0.opp_top_service_label}</b> (opportunité ${p0.opp_score}/100).`):"Lancez d'abord une recherche.";}
  else if(/ajoute.*crm/i.test(q)){const nq=q.match(/(\d+)/);const cnt=nq?Math.min(50,parseInt(nq[1])):10;runTool("add_to_crm",`ajouter ${cnt} prospects au CRM`,{count:cnt});resp=`Demande « add_to_crm » créée — approuvez-la ci-dessus pour exécuter. (Lecture : automatique ; écriture : approbation requise.)`;}
  else if(window.WebIntel&&/sans site|pas de site actif|no active website|sans site web/i.test(q)){const r=KS.S.prospects.filter(p=>{window.WebIntel.ensure(p);return (p.website_status==="INACTIVE"||p.website_status==="REGISTERED_INACTIVE"||p.website_status==="AVAILABLE"||!p.domain_name);});resp=r.length?(`Prospects sans site actif (${r.length}) :<br>`+r.slice(0,10).map(p=>`• ${p.company_name} — ${window.WebIntel.badgeSite(p)} (${p.city})`).join("<br>")):"Aucun prospect sans site actif détecté. Lancez « Check Websites » dans les résultats pour vérifier.";}
  else if(window.WebIntel&&/domaine enregistre.*sans site|registered.*inactive|enregistr.*inactif/i.test(q)){const r=KS.S.prospects.filter(p=>{window.WebIntel.ensure(p);return (p.website_status==="INACTIVE"||p.website_status==="REGISTERED_INACTIVE")&&p.domain_status==="REGISTERED";});resp=r.length?(`Domaine enregistré mais site inactif (${r.length}) :<br>`+r.slice(0,10).map(p=>`• ${p.company_name} — ${p.domain_name} (${p.city})`).join("<br>")):"Aucun prospect « domaine enregistré / site inactif » pour l'instant. Vérifiez les sites d'abord.";}
  else if(window.WebIntel&&/https|ssl|presence web|présence|digital|numérique/i.test(q)){const noH=KS.S.prospects.filter(p=>p.website_https===false).length;const ina=KS.S.prospects.filter(p=>p.website_status==="INACTIVE"||p.website_status==="REGISTERED_INACTIVE").length;const av=KS.S.prospects.filter(p=>p.domain_status==="AVAILABLE").length;const unk=KS.S.prospects.filter(p=>!p.website_status||p.website_status==="UNKNOWN").length;resp=`Opportunités de présence numérique :<br>• Site inactif : ${ina}<br>• HTTPS manquant : ${noH}<br>• Domaine potentiellement disponible : ${av}<br>• Non vérifiés : ${unk}<br><small>Observations techniques — vérification manuelle recommandée. Utilisez Smart Lists → « No Active Website ».</small>`;}
  else{resp=await KS.aiText(`Tu es Klir AI, assistant de prospection B2B. Réponds brièvement en français : ${q}`,`Je peux vous aider à chercher, qualifier, ajouter au CRM et préparer des messages. Essayez : « Trouve-moi 100 rénovations à Montréal ».`);}
  KS.S.aiLog[KS.S.aiLog.length-1]={me:false,t:resp};KS.save();render();}
function copilot(){const noAct=KS.S.prospects.filter(p=>p.rel>=75&&!p.inCrm);const icpHit=KS.S.icp?noAct.filter(p=>E.icpFit(p,KS.S.icp)>=70):[];const drafts=KS.S.campaigns.flatMap(c=>c.drafts||[]).filter(d=>d.status==="Draft");const pend=KS.S.approvals.filter(a=>a.status==="Pending");const opps=KS.S.opps.filter(o=>{const p=KS.S.prospects.find(x=>x.id===o.prospectId);return p&&!p.inCrm;});
  let h=`<p><b>Vous avez ${noAct.length} prospects qualifiés sans activité.</b>${icpHit.length?` ${icpHit.length} correspondent fortement à votre ICP.`:""} ${drafts.length?`${drafts.length} brouillon(s) en attente de revue.`:""} ${pend.length?`${pend.length} action(s) IA à approuver.`:""} ${opps.length?`${opps.length} opportunité(s) radar non traitées.`:""}</p><div class="rowb">`;
  if(icpHit.length)h+=`<button data-co="crm">Préparer liste + CRM (${Math.min(10,icpHit.length)})</button>`;
  if(noAct.length)h+=`<button data-co="msg">Préparer messages</button>`;
  h+=`</div>`; const today=new Date().toISOString().slice(0,10); const due=KS.S.crm.filter(l=>l.nextDate&&l.nextDate<=today&&l.stage!=="Won"&&l.stage!=="Lost"); if(due.length){ h+=`<h4>À recontacter aujourd’hui (${due.length})</h4>`+due.slice(0,5).map(l=>`<div class="row"><div><b>${l.company_name}</b><br><small>${l.nextAction||"Relance"} • prévu le ${l.nextDate}</small></div><button data-lead="${l.id}">Ouvrir</button></div>`).join(""); } document.getElementById("copilotOut").innerHTML=h; document.querySelectorAll("#copilotOut [data-lead]").forEach(b=>b.onclick=()=>showLead(b.dataset.lead));
  document.querySelectorAll("[data-co]").forEach(b=>b.onclick=()=>{if(b.dataset.co==="crm"){const ids=(icpHit.length?icpHit:noAct).slice(0,10).map(p=>p.id);sel=new Set(ids);curSearch=null;toCrm();}else{const ids=noAct.slice(0,5).map(p=>p.id);sel=new Set(ids);genMessagesRadar(ids);}});
  KS.audit("ai.tool.executed","sales_copilot");}
async function genMessagesRadar(ids){const rows=KS.S.prospects.filter(p=>ids.includes(p.id));if(!rows.length)return alert("Sélection vide.");if(!spendCredits(rows.length,"Messages IA"))return;
  const drafts=[];for(const p of rows){const txt=await KS.aiText(`Message B2B court pour ${p.company_name} (${p.industry}, ${p.city}).`, `Bonjour ${p.company_name}, échange de 15 min ? — ${KS.S.org?KS.S.org.name:"Klirline"}`);drafts.push({id:KS.uid("d"),prospectId:p.id,text:txt,status:"Draft"});}
  KS.S.campaigns.unshift({id:KS.uid("c"),name:`Brouillons Copilot — ${rows.length} prospects`,prospects:rows.map(p=>p.id),drafts,status:"Review",created:new Date().toLocaleDateString(),message:"Objet : Une question concernant votre activité"});KS.save();KS.addActivity("Copilot : brouillons en Review");KS.notify("Copilot : campagne en Review, à valider.");nav("/campaigns");}
async function radarRun(){if(window.KlirTeam&&!window.KlirTeam.guard("search"))return;if(!spendCredits(5,"Scan Radar"))return;
  const icp=KS.S.icp; const base=icp?{industry:icp.industry,cityKey:Object.keys(KlirData.CITIES).find(k=>KlirData.CITIES[k].city===icp.city)||"default",quantity:20,size:icp.size,raw:"radar"}:(KS.S.searches[0]?KS.S.searches[0].params:{industry:"construction",cityKey:"default",city:KlirData.CITIES.default,quantity:20,raw:"radar"});
  base.city=KlirData.CITIES[base.cityKey]||KlirData.CITIES.default; base.raw="radar"+Date.now();
  const raw=E.genProspects(base,25); const known=new Set(KS.S.prospects.map(p=>E.fingerprint(p)));
  let added=0;
  for(const p of raw){if(known.has(E.fingerprint(p)))continue;known.add(E.fingerprint(p));
    const sc=E.scoreProspect(p,base,KS.S.weights);Object.assign(p,{dq:sc.data_quality_score,rel:sc.commercial_relevance_score,conf:sc.confidence_score,intent:sc.intent_score,opp:sc.opportunity_score,ai:E.aiAnalysis(p,base),searchId:"radar",icp:icp?E.icpFit(p,icp):null});
    KS.S.prospects.unshift(p);added++;
    try{if(window.OppEngine)window.OppEngine.attach(p,base);}catch(e){}
    const hot=p.rel>=80||(icp&&p.icp>=70)||p.signals.includes("Entreprise récente");
    if(hot&&(KS.S.radarCfg.signals.includes(p.signals[0]||"")||p.rel>=85))KS.S.opps.unshift({id:KS.uid("o"),prospectId:p.id,score:icp?Math.max(p.rel,p.icp):p.rel,kind:p.signals.includes("Entreprise récente")?"Nouveau prospect":"Signal commercial",signal:p.signals[0]||"Correspondance ICP",why:`${p.industry||"Secteur n.d."} à ${p.city}, qualité ${p.dq}/100${icp?`, ICP ${p.icp}/100`:""}.`,action:"Ajouter au CRM → Préparer un message.",at:new Date().toLocaleString()});
    if(added>=12)break;}
  let chg=0; for(const id of KS.S.watch){const p=KS.S.prospects.find(x=>x.id===id);if(p&&window.KlirSecurity.random()>0.5){const sg=["Recrutement","Expansion","Nouveau site"][Math.floor(window.KlirSecurity.random()*3)];if(!p.signals.includes(sg)){p.signals.push(sg);chg++;KS.S.opps.unshift({id:KS.uid("o"),prospectId:p.id,score:p.rel,kind:"Changement suivi",signal:sg,why:`Changement détecté chez un prospect suivi : ${sg}.`,action:"Revoir la fiche → Relancer.",at:new Date().toLocaleString()});}}}
  KS.S.lastRadar=new Date().toLocaleString();KS.S.radarStats={at:KS.S.lastRadar,added:added,changes:chg,opps:KS.S.opps.length};KS.save();KS.notify(`🔥 Radar : ${added} nouveaux prospects, ${KS.S.opps.filter(o=>{const p=KS.S.prospects.find(x=>x.id===o.prospectId);return p&&!p.inCrm;}).length} opportunités ouvertes.`);KS.audit("radar.scan",added+" nouveaux");render();}
async function enrichSelected(){if(window.KlirTeam&&!window.KlirTeam.guard("search"))return;const rows=KS.S.prospects.filter(p=>sel.has(p.id));if(!rows.length)return alert("Sélectionnez des prospects.");if(!spendCredits(rows.length*2,"Enrichissement waterfall"))return;
  let filled=0;for(const p of rows){const r=E.enrichWaterfall(p,KS.S.integrations);filled+=r.filled.length;const sc=E.scoreProspect(p,KS.S.searches.find(s=>s.id===p.searchId)?.params||{industry:p.industry_key,cityKey:"default",city:KlirData.CITIES.default},KS.S.weights);p.dq=sc.data_quality_score;p.rel=sc.commercial_relevance_score;p.intent=sc.intent_score;p.opp=sc.opportunity_score;}
  if(KS.S.integrations.osm&&KS.S.integrations.osm.on&&window.KlirSources&&window.KlirSources.osm){ for(const p of rows){ if(!p.address)continue; try{ const g=await window.KlirSources.osm.lookup(p.address+", "+p.city); if(g){ p.geo=g; p.addrVerified=g.label; filled++; } }catch(e){} } } KS.save();KS.addActivity(`Enrichissement waterfall : ${filled} champs complétés sur ${rows.length} prospects`);KS.audit("enrichment.completed",rows.length+" prospects");render();}
function importCsvText(txt){const lines=txt.split(/\r?\n/).filter(l=>l.trim());if(lines.length<2)return {err:"Fichier vide."};
  const sep=(lines[0].match(/;/g)||[]).length>(lines[0].match(/,/g)||[]).length?";":",";
  const head=lines[0].toLowerCase().split(sep).map(h=>h.trim());
  const col=(...ns)=>head.findIndex(h=>ns.some(n=>h.includes(n)));
  const ci={name:col("nom","name","societe","company"),city:col("ville","city"),phone:col("tel","phone"),email:col("email","mail"),ind:col("secteur","industr","activite"),web:col("site","web","url")};
  if(ci.name<0)return {err:"Colonne nom introuvable."};
  const known=new Set(KS.S.prospects.map(p=>E.fingerprint(p)));const out=[];let dups=0;
  for(const ln of lines.slice(1,1001)){const c=ln.split(sep).map(v=>window.KlirSecurity.text(v.replace(/^"|"$/g,""),500));const name=(c[ci.name]||"").trim();if(!name)continue;
    const p={id:KS.uid("p"),company_name:name,city:ci.city>=0?(c[ci.city]||"Montréal"):"Montréal",province:"QC",country:"Canada",address:"",postal_code:"",phone:ci.phone>=0?(c[ci.phone]||""):"",public_email:ci.email>=0?(c[ci.email]||""):"",industry:ci.ind>=0?(c[ci.ind]||"Services"):"Services",industry_key:"services",website:ci.web>=0?(c[ci.web]||""):"",domain:"",description:"",employee_range:"11–50",social_links:{},source:"Import client",source_url:"",last_verified:new Date().toISOString().slice(0,10),signals:[],status:"New"};
    p.domain=E.normDomain(p.website);
    if(known.has(E.fingerprint(p))){dups++;continue;}known.add(E.fingerprint(p));
    const sc=E.scoreProspect(p,{industry:p.industry_key,cityKey:"default",city:KlirData.CITIES.default},KS.S.weights);p.dq=sc.data_quality_score;p.rel=sc.commercial_relevance_score;p.conf=sc.confidence_score;p.intent=sc.intent_score;p.opp=sc.opportunity_score;p.ai="Import client — à qualifier.";p.searchId="import";
    try{if(window.OppEngine)window.OppEngine.attach(p,{industry:p.industry_key,cityKey:"default",city:window.KlirData.CITIES.default});}catch(e){}
    out.push(p);}
  return {rows:out,dups};}
function drawCharts(){const c=document.getElementById("ch");if(c){const x=c.getContext("2d");x.fillStyle="#6366f1";[40,70,55,90,80,110,95].forEach((v,i)=>x.fillRect(10+i*48,150-v,30,v));}
  const c2=document.getElementById("ch2");if(c2){const x=c2.getContext("2d");x.fillStyle="#10b981";[30,60,90,70,120,140,110].forEach((v,i)=>x.fillRect(10+i*80,170-v,50,v));}}
